{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "better-compact",
  "version": "0.3.2",
  "type": "module",
  "description": "OpenCode plugin that improves long-session context with boundary-time pruning",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "context",
    "pruning",
    "optimization",
    "tokens"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AshishKumar4/better-compact.git",
    "directory": "packages/opencode"
  },
  "bugs": {
    "url": "https://github.com/AshishKumar4/better-compact/issues"
  },
  "homepage": "https://github.com/AshishKumar4/better-compact#readme",
  "author": "AshishKumar4",
  "license": "AGPL-3.0-or-later",
  "engines": {
    "opencode": ">=1.17.13 <2"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.13 <2",
    "@opentui/core": ">=0.4.2",
    "@opentui/solid": ">=0.4.2"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.13",
    "@opencode-ai/sdk": "^1.17.13",
    "@opentui/core": "^0.4.2",
    "@opentui/solid": "^0.4.2",
    "@types/node": "^25.5.0",
    "jsonc-parser": "^3.3.1",
    "solid-js": "^1.9.12",
    "tsup": "^8.5.1",
    "tsx": "^4.21.0",
    "typescript": "^6.0.2",
    "@better-compact/core": "0.4.0"
  },
  "files": [
    "dist/index.js",
    "dist/index.d.ts",
    "dist/tui.js",
    "dist/tui.d.ts",
    "better-compact.schema.json",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "pnpm run clean && tsup && tsc --emitDeclarationOnly",
    "verify:package": "node scripts/verify-package.mjs",
    "verify:release": "node scripts/verify-release.mjs",
    "smoke:install": "node scripts/smoke-opencode-install.mjs",
    "check:package": "pnpm run build && pnpm run verify:package",
    "dev": "opencode plugin dev",
    "typecheck": "tsc --noEmit",
    "test": "node --import tsx --import ./tests/setup.ts --test tests/*.test.ts",
    "test:tui": "bun --bun test --preload @opentui/solid/runtime-plugin-support ./tests/tui-layout.visual.tsx ./tests/tui-progress-channel.visual.tsx ./tests/tui-command.visual.ts ./tests/global-settings.visual.ts"
  }
}
